def f(gi):
    bg=Counter(x for r in gi for x in r).most_common(1)[0][0]
    cands=[c for c in set(x for r in gi for x in r) if c!=bg]
    best=None
    for c in cands:
        H=len(gi); W=len(gi[0]); seen=set(); n=0
        for i in range(H):
            for j in range(W):
                if gi[i][j]==c and (i,j) not in seen:
                    st=[(i,j)]; seen.add((i,j))
                    while st:
                        y,x=st.pop()
                        for dy in(-1,0,1):
                            for dx in(-1,0,1):
                                ny,nx=y+dy,x+dx
                                if 0<=ny<H and 0<=nx<W and gi[ny][nx]==c and (ny,nx) not in seen:
                                    seen.add((ny,nx)); st.append((ny,nx))
                    n+=1
        if best is None or n>best[0]: best=(n,c)
    return [[best[1]]]
