            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def comps(g,color,conn=8):
    H=len(g); W=len(g[0]); seen=set(); res=[]
    nb=[(dy,dx) for dy in(-1,0,1) for dx in(-1,0,1) if conn==8 or (dy==0 or dx==0)]
    for i in range(H):
        for j in range(W):
            if g[i][j]==color and (i,j) not in seen:
                st=deque([(i,j)]); seen.add((i,j)); cells=[]
                while st:
                    y,x=st.popleft(); cells.append((y,x))
                    for dy,dx in nb:
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and g[ny][nx]==color and (ny,nx) not in seen:
                            seen.add((ny,nx)); st.append((ny,nx))
                ys=[y for y,_ in cells]; xs=[x for _,x in cells]
                touches=any(y in (0,H-1) or x in (0,W-1) for y,x in cells)
                res.append({'size':len(cells),'bbox':(max(ys)-min(ys)+1,max(xs)-min(xs)+1),'rect':len(set((y-min(ys),x-min(xs)) for y,x in cells))==len(cells),'touches':touches})
    return res
