def largest_color(g):
    H=len(g); W=len(g[0]); best=None
    for c in set(x for r in g for x in r):
        for i in range(H):
            for j in range(W):
                if g[i][j]==c and (i,j) not in {(a,b) for a,b in []}:
                    st=deque([(i,j)]); seen={(i,j)}
                    while st:
                        y,x=st.popleft()
                        for dy in(-1,0,1):
                            for dx in(-1,0,1):
                                ny,nx=y+dy,x+dx
                                if 0<=ny<H and 0<=nx<W and g[ny][nx]==c and (ny,nx) not in seen:
                                    seen.add((ny,nx)); st.append((ny,nx))
                    sz=len(seen)
                    if best is None or sz>best[0]: best=(sz,c)
    return best
