def enclosed(g):
    H=len(g);W=len(g[0])
    cnt=Counter(x for r_ in g for x in r_)
    bg=cnt.most_common(1)[0][0]
    shape=None
    for c in [v for v in cnt if v!=bg]:
        cs4=cc(g,c,4)
        if len(cs4)>=2 and all(len(q)==4 for q in cs4): shape=c; break
    blocked=set(p for blk in cc(g,shape,4) for p in blk)
    st=deque((i,j) for i in range(H) for j in range(W) if (i,j) not in blocked)
    seen=set(st)
    while st:
        y,x=st.popleft()
        for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
            n=(y+dy,x+dx)
            if 0<=n[0]<H and 0<=n[1]<W and n not in seen and (n not in blocked):
                seen.add(n); st.append(n)
    enc=[p for p in seen if False] 
    unreach=[(i,j,g[i][j]) for i in range(H) for j in range(W) if (i,j) not in seen and (i,j) not in blocked]
    return Counter(g[i][j] for i,j in unreach)
